         reference = window.GxSuperAppApi.call("PayWithoutUI", parmsArray).then(
            function (value) {
                return value;
            },
            function (error) {
                this.internal_errorCode = 1;
            this.internal_errorDesc = error;
            });
      } catch (error) {
         this.internal_errorCode = 999;
       this.internal_errorDesc = error.message;
      }
      return reference;
   },

   exit: function () {
